use alloc::string::String;

pub const DEFAULT_FIREWALL_CONF: &str = r#"
# ========================================================
# Generated by iptables-save / axfirewall declarative conf
# ========================================================
*filter
:INPUT ACCEPT [0:0]
:OUTPUT ACCEPT [0:0]

# 1. 管理平面白名单 (仅放行 10.0.2.2/32 访问 8888 端口)
-A INPUT -p tcp -s 10.0.2.2/32 --dport 8888 -j ACCEPT

# 2. 兜底保护管理口 (拦截其他所有来源对 8888 的探测)
-A INPUT -p tcp --dport 8888 -j DROP

# 3. 业务平面审计与放行 (放行 10.0.2.0/24 访问 5555 并记录审计日志)
-A INPUT -p tcp -s 10.0.2.0/24 --dport 5555 -j LOG_ACCEPT

# 4. 封闭未开放的高危端口
-A INPUT -p tcp --dport 9999 -j DROP

COMMIT
"#;

pub fn load_rules_from_str(config_text: &str) -> Result<usize, String> {
    let mut count = 0;

    for (line_no, line) in config_text.lines().enumerate() {
        let trimmed = line.trim();

        if trimmed.is_empty()
            || trimmed.starts_with('#')
            || trimmed.starts_with("//")
            || trimmed.starts_with('*')
            || trimmed.starts_with(':')
            || trimmed == "COMMIT"
        {
            continue;
        }

        crate::execute_cmd(trimmed).map_err(|err| {
            alloc::format!(
                "Config error at line {}: '{}' -> {}",
                line_no + 1,
                trimmed,
                err
            )
        })?;

        count += 1;
    }

    Ok(count)
}

pub fn export_rules_as_conf() -> String {
    let mut conf = String::from("# Generated by axfirewall export\n*filter\n:INPUT ACCEPT [0:0]\n:OUTPUT ACCEPT [0:0]\n");
    let lock = crate::FIREWALL_ENGINE.read();

    if let Some(ref engine) = *lock {
        for rule in &engine.rules {
            let chain = match rule.direction {
                Some(crate::Direction::Inbound) => "INPUT",
                Some(crate::Direction::Outbound) => "OUTPUT",
                None => "FORWARD",
            };

            let verdict = match rule.verdict {
                crate::FilterVerdict::Accept => "ACCEPT",
                crate::FilterVerdict::Drop => "DROP",
                crate::FilterVerdict::LogAccept => "LOG_ACCEPT",
                crate::FilterVerdict::LogDrop => "LOG_DROP",
            };

            let proto_part = match rule.proto {
                Some(crate::L4Protocol::Tcp) => " -p tcp",
                Some(crate::L4Protocol::Udp) => " -p udp",
                Some(crate::L4Protocol::Icmp) => " -p icmp",
                _ => "",
            };

            let src_part = match rule.src_cidr {
                Some(ref cidr) => alloc::format!(" -s {}/{}", cidr.addr, cidr.prefix_len),
                None => String::new(),
            };

            let dst_part = match rule.dst_cidr {
                Some(ref cidr) => alloc::format!(" -d {}/{}", cidr.addr, cidr.prefix_len),
                None => String::new(),
            };

            let port_part = match rule.dst_port {
                Some(port) => alloc::format!(" --dport {}", port),
                None => String::new(),
            };

            conf.push_str(&alloc::format!(
                "-A {}{}{}{}{} -j {}\n",
                chain,
                proto_part,
                src_part,
                dst_part,
                port_part,
                verdict
            ));
        }
    }

    conf.push_str("COMMIT\n");
    conf
}